/**
 * Core (OSS) sidebar menu items for Conductor UI.
 *
 * These items are merged with plugin-registered items in UiSidebar.
 * - Executions submenu (Workflow, Scheduler, Queue Monitor)
 * - Run Workflow button
 * - Definitions submenu (Workflow, Agents, Task, Event Handler, Scheduler)
 * - Help menu
 * - API Docs
 */

import CodeIcon from "@mui/icons-material/Code";
import PlayIcon from "@mui/icons-material/PlayArrowOutlined";
import PlaylistPlayIcon from "@mui/icons-material/PlaylistPlay";
import SmartToyOutlinedIcon from "@mui/icons-material/SmartToyOutlined";
import SupportIcon from "@mui/icons-material/Support";
import WebhookOutlinedIcon from "@mui/icons-material/WebhookOutlined";
import RunWorkflowButton from "components/providers/sidebar/RunWorkflowButton";
import { MenuItemType } from "components/providers/sidebar/types";
import { FEATURES, featureFlags } from "utils";
import {
  AGENT_DEFINITION_URL,
  AGENT_EXECUTIONS_URL,
  AGENT_SECRETS_URL,
  EVENT_HANDLERS_URL,
  NEW_TASK_DEF_URL,
  RUN_WORKFLOW_URL,
  SCHEDULER_DEFINITION_URL,
  SCHEDULER_EXECUTION_URL,
  SKILLS_URL,
  TASK_DEF_URL,
  TASK_QUEUE_URL,
  WORKFLOW_DEFINITION_URL,
  WORKFLOW_EXECUTION_URL,
} from "utils/constants/route";

const isPlayground = featureFlags.isEnabled(FEATURES.PLAYGROUND);
const hideFeedbackForm = !featureFlags.isEnabled(FEATURES.SHOW_FEEDBACK_FORM);
const hideScheduler = !featureFlags.isEnabled(FEATURES.SCHEDULER);
const hideAgentspan = !featureFlags.isEnabled(
  FEATURES.CONDUCTOR_INTEGRATIONS_AI_ENABLED,
);

/**
 * Core sidebar position constants. Root and submenus both use 100, 200, 300, ...
 * so plugins can inject items in between (e.g. position 150 between 100 and 200).
 * Export for orkes-conductor-ui to reference when registering sidebar items.
 */
const CORE_SIDEBAR_POSITIONS = {
  // Root level (top-level menu items)
  ROOT: {
    executionsSubMenu: 100,
    runWorkflow: 200,
    definitionsSubMenu: 300,
    helpMenu: 400,
    swaggerItem: 500,
  },
  // Executions submenu children
  EXECUTIONS: {
    workflowExeItem: 100,
    schedulerExeItem: 185,
    queueMonitorItem: 200,
  },
  // Definitions submenu children
  DEFINITIONS: {
    workflowDefItem: 100,
    agentDefItem: 150,
    taskDefItem: 200,
    eventHandlerDefItem: 300,
    schedulerDefItem: 350,
  },
  // Help submenu children
  HELP: {
    docsItem: 100,
    requestsItem: 200,
    supportItem: 300,
  },
} as const;

/**
 * Returns the core OSS sidebar menu items. Accepts `open` for the Run Workflow
 * button component which depends on sidebar open state.
 * Each item has a numeric position so plugins can inject between (e.g. 150 between 100 and 200).
 */
export function getCoreSidebarItems(open: boolean): MenuItemType[] {
  const R = CORE_SIDEBAR_POSITIONS.ROOT;
  const E = CORE_SIDEBAR_POSITIONS.EXECUTIONS;
  const D = CORE_SIDEBAR_POSITIONS.DEFINITIONS;
  const H = CORE_SIDEBAR_POSITIONS.HELP;

  return [
    // Executions submenu - core items only
    {
      id: "executionsSubMenu",
      title: "Executions",
      icon: <PlaylistPlayIcon />,
      linkTo: "",
      shortcuts: [],
      hotkeys: "",
      hidden: false,
      position: R.executionsSubMenu,
      items: [
        {
          id: "workflowExeItem",
          title: "Workflow",
          icon: null,
          linkTo: "/executions",
          activeRoutes: [WORKFLOW_EXECUTION_URL.WF_ID_TASK_ID],
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: E.workflowExeItem,
        },
        {
          id: "schedulerExeItem",
          title: "Scheduler",
          icon: null,
          linkTo: SCHEDULER_EXECUTION_URL,
          shortcuts: [],
          hotkeys: "",
          hidden: hideScheduler,
          position: E.schedulerExeItem,
        },
        {
          id: "queueMonitorItem",
          title: "Queue Monitor",
          icon: null,
          linkTo: TASK_QUEUE_URL.BASE,
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: E.queueMonitorItem,
        },
      ],
    },
    // Agents submenu (embedded Conductor-Agents) - hidden unless CONDUCTOR_INTEGRATIONS_AI_ENABLED
    {
      id: "agentspanSubMenu",
      title: "Agents",
      icon: <SmartToyOutlinedIcon />,
      linkTo: "",
      shortcuts: [],
      hotkeys: "",
      hidden: hideAgentspan,
      position: 250,
      items: [
        {
          id: "agentExeItem",
          title: "Executions",
          icon: null,
          linkTo: AGENT_EXECUTIONS_URL.BASE,
          activeRoutes: [AGENT_EXECUTIONS_URL.ID_TASK_ID],
          shortcuts: [],
          hotkeys: "",
          hidden: hideAgentspan,
          position: 200,
        },
        {
          id: "agentSkillsItem",
          title: "Skills",
          icon: null,
          linkTo: SKILLS_URL.BASE,
          shortcuts: [],
          hotkeys: "",
          hidden: true,
          position: 300,
        },
        {
          id: "agentSecretsItem",
          title: "Secrets",
          icon: null,
          linkTo: AGENT_SECRETS_URL,
          shortcuts: [],
          hotkeys: "",
          hidden: hideAgentspan,
          position: 400,
        },
      ],
    },
    // Run Workflow button
    {
      id: "runWorkflow",
      title: "Run Workflow",
      icon: <PlayIcon />,
      linkTo: RUN_WORKFLOW_URL,
      shortcuts: [],
      hidden: true,
      position: R.runWorkflow,
      component: <RunWorkflowButton open={open} />,
    },
    // Definitions submenu - core items only
    {
      id: "definitionsSubMenu",
      title: "Definitions",
      icon: <CodeIcon />,
      linkTo: "",
      shortcuts: [],
      hotkeys: "",
      hidden: false,
      position: R.definitionsSubMenu,
      items: [
        {
          id: "workflowDefItem",
          title: "Workflow",
          icon: null,
          linkTo: WORKFLOW_DEFINITION_URL.BASE,
          activeRoutes: [
            WORKFLOW_DEFINITION_URL.NEW,
            WORKFLOW_DEFINITION_URL.NAME_VERSION,
          ],
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: D.workflowDefItem,
        },
        {
          id: "agentDefItem",
          title: "Agents",
          icon: null,
          linkTo: AGENT_DEFINITION_URL.BASE,
          shortcuts: [],
          hotkeys: "",
          hidden: hideAgentspan,
          position: D.agentDefItem,
        },
        {
          id: "taskDefItem",
          title: "Task",
          icon: null,
          linkTo: TASK_DEF_URL.BASE,
          activeRoutes: [NEW_TASK_DEF_URL, TASK_DEF_URL.NAME],
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: D.taskDefItem,
        },
        {
          id: "eventHandlerDefItem",
          title: "Event Handler",
          icon: null,
          linkTo: EVENT_HANDLERS_URL.BASE,
          activeRoutes: [EVENT_HANDLERS_URL.NEW, EVENT_HANDLERS_URL.NAME],
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: D.eventHandlerDefItem,
        },
        {
          id: "schedulerDefItem",
          title: "Scheduler",
          icon: null,
          linkTo: SCHEDULER_DEFINITION_URL.BASE,
          activeRoutes: [
            SCHEDULER_DEFINITION_URL.NEW,
            SCHEDULER_DEFINITION_URL.NAME,
          ],
          shortcuts: [],
          hotkeys: "",
          hidden: hideScheduler,
          position: D.schedulerDefItem,
        },
      ],
    },
    // Help menu
    {
      id: "helpMenu",
      title: "Help",
      icon: <SupportIcon />,
      linkTo: "",
      shortcuts: [],
      hotkeys: "",
      hidden: false,
      position: R.helpMenu,
      items: [
        {
          id: "docsItem",
          title: "Docs",
          icon: null,
          linkTo: "https://orkes.io/content/",
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: H.docsItem,
          isOpenNewTab: true,
        },
        {
          id: "requestsItem",
          title: "Requests",
          icon: null,
          linkTo:
            "https://orkes.io/orkes-cloud-free-trial?utm_source=playground",
          shortcuts: [],
          hotkeys: "",
          hidden: hideFeedbackForm,
          position: H.requestsItem,
          isOpenNewTab: true,
        },
        {
          id: "supportItem",
          title: "Support",
          icon: null,
          linkTo: isPlayground
            ? "https://community.orkes.io/ "
            : "https://orkeshelp.zendesk.com/hc/en-us/requests/new",
          shortcuts: [],
          hotkeys: "",
          hidden: false,
          position: H.supportItem,
          isOpenNewTab: true,
        },
      ],
    },
    // API Docs
    {
      id: "swaggerItem",
      title: "API Docs",
      icon: <WebhookOutlinedIcon />,
      linkTo: "/api-reference",
      shortcuts: [],
      hotkeys: "",
      hidden: false,
      position: R.swaggerItem,
    },
  ];
}
